package demo;

import org.apache.commons.lang3.tuple.Pair;

/** Uses a resolved dependency and a source generated by the build tool. */
public class Consumer {
    /** Builds a labelled value.
     * @param value user input
     * @return the build label and supplied value
     */
    public Pair<String, String> labelled(String value) {
        return Pair.of(BuildInfo.NAME, value);
    }
}
